const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const cvText = (body.cvText || body.cv_text || '').trim();
  const jobDescription = (body.jobDescription || body.job_description || '').trim();
  const targetRole = (body.targetRole || body.target_role || 'Target Role').trim();
  const candidateName = (body.candidateName || body.candidate_name || '').trim();

  if (!cvText || cvText.length < 40) {
    throw new Error('CV text is required and must contain at least 40 characters.');
  }
  if (!jobDescription || jobDescription.length < 30) {
    throw new Error('Job description is required and must contain at least 30 characters.');
  }

  results.push({
    json: {
      cvText,
      jobDescription,
      targetRole,
      candidateName
    }
  });
}

return results;

const item = $input.first().json;

const SYSTEM_PROMPT = `You are an elite ATS recruitment specialist and career strategist. 
Analyze the candidate's existing CV and target Job Description.

Perform a strict gap analysis:
1. Extract essential hard skills, programming languages, platforms, and methodologies explicitly demanded by the JD.
2. Identify soft skills and leadership indicators emphasized in the JD.
3. Identify missing or weakly phrased terms in the CV that can be enhanced.
4. Determine the primary job title and key competency themes.

Return strictly valid JSON with this schema (no markdown, no code fences, no conversational text):
{
  "target_role": "Target Job Title",
  "initial_ats_score": 60,
  "high_priority_keywords": ["keyword1", "keyword2"],
  "medium_priority_keywords": ["keyword3", "keyword4"],
  "recommended_competency_categories": {
    "Core Skills": ["skill1", "skill2"],
    "Tools & Technologies": ["tool1", "tool2"],
    "Methodologies & Domain": ["method1", "method2"]
  },
  "strategic_advice": "1-2 sentence core positioning strategy for this candidate"
}`;

const userMessage = `CANDIDATE CV:\n${item.cvText}\n\nTARGET JOB DESCRIPTION:\n${item.jobDescription}\n\nTARGET ROLE HINT: ${item.targetRole}`;

const payload = {
  model: "openai/gpt-oss-120b",
  temperature: 0.2,
  max_tokens: 2000,
  response_format: { type: "json_object" },
  messages: [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: userMessage }
  ]
};

return [{
  json: {
    ...item,
    stage1Payload: JSON.stringify(payload)
  }
}];

const item = $input.first().json;
let analysis = {};
let error = '';

if (item.error || item.errorMessage || item.statusCode >= 400) {
  error = item.error || item.errorMessage || ('HTTP Error ' + item.statusCode);
}

try {
  if (!error && item.choices && item.choices.length > 0) {
    let text = item.choices[0].message.content || '';
    text = text.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
    text = text.replace(/^```[a-z]*\n?/gm, '').replace(/```$/gm, '').trim();
    analysis = JSON.parse(text);
  }
} catch (e) {
  error = 'Stage 1 parsing failed: ' + e.message;
}

let prevData = {};
try {
  prevData = $('Validate Input').first().json;
} catch (e) {}

return [{
  json: {
    ...prevData,
    analysis,
    errorStage1: error
  }
}];

const item = $input.first().json;
const analysis = item.analysis || {};
const keywords = [...(analysis.high_priority_keywords || []), ...(analysis.medium_priority_keywords || [])];

const SYSTEM_PROMPT = `You are a world-class executive CV writer and ATS optimization brain.
Your task is to take the candidate's original CV, the target Job Description, and the Gap Analysis keywords, and produce a fully tailored, ATS-compliant CV.

CRITICAL CONSTRAINTS:
1. ZERO FABRICATION: Retain truthful career history, dates, degrees, company names, and core responsibilities. Never invent jobs, institutions, or untrue technical capabilities.
2. STRATEGIC POSITIONING: Tailor the Professional Summary and Subtitle specifically for the target role.
3. HIGH IMPACT BULLETS: Rewrite experience bullet points using strong action verbs and the Google XYZ format ("Accomplished [X] as measured by [Y] by doing [Z]"). Weave in the target keywords seamlessly.
4. CATEGORIZED SKILLS: Organize technical and domain skills to match the nomenclature used in the JD.
5. CLEAN MARKDOWN: The optimized CV MUST be formatted in clean, standard Markdown with standard headings (# Header, ## Summary, ## Skills, ## Experience, ## Education, ## Projects/Certifications).
6. CHANGE TRACKING: Document 5 to 10 significant bullet enhancements in the changes array.

Return strictly valid JSON with this schema (no markdown fences, no conversational text):
{
  "target_title": "Job Title",
  "projected_ats_score": 94,
  "keywords_injected": ["keyword1", "keyword2"],
  "changes": [
    {
      "section": "Experience - Company Name",
      "original": "Original CV bullet or excerpt",
      "updated": "Enhanced bullet with action verbs & keywords",
      "keywords_added": ["term1"]
    }
  ],
  "optimized_markdown": "# Candidate Name\n**Target Role** | Contact Info\n\n## Professional Summary\n...\n\n## Core Competencies\n...\n\n## Professional Experience\n...\n\n## Education\n..."
}`;

const userMessage = `ORIGINAL CV:\n${item.cvText}\n\nTARGET JOB DESCRIPTION:\n${item.jobDescription}\n\nKEYWORDS TO WEAVE IN:\n${keywords.join(', ')}\n\nTARGET POSITIONING:\n${analysis.strategic_advice || ''}`;

const payload = {
  model: "openai/gpt-oss-120b",
  temperature: 0.3,
  max_tokens: 3500,
  response_format: { type: "json_object" },
  messages: [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: userMessage }
  ]
};

return [{
  json: {
    ...item,
    stage2Payload: JSON.stringify(payload)
  }
}];

const item = $input.first().json;
let parsed = {};
let error = '';

if (item.error || item.errorMessage || item.statusCode >= 400) {
  error = item.error || item.errorMessage || ('HTTP Error ' + item.statusCode);
}

try {
  if (!error && item.choices && item.choices.length > 0) {
    let text = item.choices[0].message.content || '';
    text = text.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
    text = text.replace(/^```[a-z]*\n?/gm, '').replace(/```$/gm, '').trim();
    parsed = JSON.parse(text);
  }
} catch (e) {
  error = 'Stage 2 parsing failed: ' + e.message;
}

let prev = {};
try {
  prev = $('Parse Stage 1').first().json;
} catch (e) {}

const markdown = parsed.optimized_markdown || '';

// Generate clean ATS HTML
function markdownToHtml(md) {
  let html = md
    .replace(/^# (.*$)/gim, '<h1 class="cv-name">$1</h1>')
    .replace(/^## (.*$)/gim, '<h2 class="cv-section-title">$1</h2>')
    .replace(/^### (.*$)/gim, '<h3 class="cv-item-title">$1</h3>')
    .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/gim, '<em>$1</em>')
    .replace(/^\s*-\s*(.*$)/gim, '<li class="cv-bullet">$1</li>')
    .replace(/\n{2,}/gim, '</p><p>')
    .replace(/\n/gim, '<br>');
  return '<div class="cv-document"><p>' + html + '</p></div>';
}

const html = markdownToHtml(markdown);
const plainText = markdown.replace(/[#*`_]/g, '');

const initialScore = (prev.analysis && prev.analysis.initial_ats_score) || 60;
const projectedScore = parsed.projected_ats_score || 92;
const keywordsInjected = parsed.keywords_injected || (prev.analysis && prev.analysis.high_priority_keywords) || [];
const changes = parsed.changes || [];

return [{
  json: {
    status: error ? 'error' : 'success',
    error: error || null,
    data: error ? null : {
      targetTitle: parsed.target_title || prev.targetRole || 'Target Role',
      optimizedMarkdown: markdown,
      optimizedHtml: html,
      optimizedText: plainText,
      stats: {
        initialAtsScore: initialScore,
        projectedAtsScore: projectedScore,
        keywordsCount: keywordsInjected.length,
        changesCount: changes.length
      },
      keywordsInjected: keywordsInjected,
      changes: changes
    }
  }
}];
